def count_subarrays(nums):
    res = 0
    stack = []  # [value, count], values strictly decreasing from bottom to top
    for x in nums:
        # smaller values can never be a left boundary once x appears
        while stack and stack[-1][0] < x:
            stack.pop()
        if stack and stack[-1][0] == x:
            stack[-1][1] += 1
        else:
            stack.append([x, 1])
        # every counted occurrence of x so far is a valid left boundary
        res += stack[-1][1]
    return res
